-- Short stories for casual typing. The server hands each player stories they have not finished yet;
-- once a player has finished every story in a language, their list for that language starts again.
-- Only the Edge Functions (service role) touch these tables.

create table public.stories (
  id serial primary key,
  lang text not null check (lang in ('en', 'fil')),
  body text not null,
  unique (lang, body)
);

create table public.story_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  story_id integer not null references public.stories (id) on delete cascade,
  completed_at timestamptz not null default now(),
  primary key (user_id, story_id)
);

alter table public.test_issues add column story_ids integer[] not null default '{}';

alter table public.stories enable row level security;
alter table public.story_progress enable row level security;
revoke all on public.stories, public.story_progress from anon, authenticated;

on conflict (lang, body) do nothing;
